window.FILM_WORK_PROMPTS={"work_id":"src-5fe467fa61820a5e","records":[{"work_id":"src-5fe467fa61820a5e","frame_id":"FG-4d1f7a54687b4fd0","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (1000).jpg","source_page":"https://film-grab.com/2016/01/05/the-big-blue/","scene":"画面主体为广阔无垠的深蓝色海面，水面布满细碎的波光，上方是灰白色的天空，海平线横贯画面上方，整体环境空旷寂静。","analysis":"构图极简，海平线位于画面上部约五分之一处，将画面分割为大面积的海面与狭长的天空。视角为轻微俯视，海面占据画面约五分之四的比例。光线柔和漫射，无强烈阴影，色彩由近处的深蓝向远处的灰白渐变，水面呈现细密的颗粒状反光质感。","prompt":"这是一张极简风格的海景摄影作品。画面主体是广阔平静的深蓝色海面，占据了绝大部分视野。海面上密布着无数细小的白色波光，呈现出一种闪烁的颗粒质感。海平线笔直且清晰，位于画面上方约五分之一处，将海面与上方灰白色的天空分隔开来。天空呈现出朦胧的雾感，没有明显的云层细节。整体光线均匀柔和，色彩从近景的深蓝逐渐过渡到远景的灰白，营造出一种空旷、宁静且略带忧郁的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:47:10-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (1000).jpg","observed_dimensions":[1024,435],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.468,"observed_resolution":"normal","observation_limits":[],"id":"VP-3c96b0a9ac9aaf0d","origin":"visual"},{"work_id":"src-5fe467fa61820a5e","frame_id":"FG-624b3de4732cceb0","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (1023).jpg","source_page":"https://film-grab.com/2016/01/05/the-big-blue/","scene":"金发人物侧身面向右侧窗户，头戴红黑花纹头巾，身穿深色厚外套，右手抬起贴近脸颊，右侧悬挂彩色条纹织物，左侧为深色木质墙面。","analysis":"画面采用侧面视角，人物占据画面左侧约三分之一区域，右侧大面积被彩色条纹织物填充。人物上半身可见，头部微仰，光线从右侧窗户射入，照亮面部轮廓、手部及头巾边缘，形成明显的明暗对比。背景左侧处于阴影中，整体色调偏冷，与右侧织物的暖色条纹形成视觉反差。","prompt":"侧面视角的金发人物，头戴红黑相间花纹头巾，佩戴眼镜，身穿深色厚外套，右手抬起轻触脸颊，面部朝向右侧。人物位于画面左侧，右侧前景悬挂着大面积彩色条纹织物，包含红、蓝、白、黑等横向条纹。左侧背景为深色木质板墙，光线从右侧窗户射入，照亮人物面部、手部及头巾边缘，形成强烈的侧光效果，背景处于阴影中，画面具有胶片质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:47:18-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (1023).jpg","observed_dimensions":[1024,435],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.584,"observed_resolution":"normal","observation_limits":[],"id":"VP-86eede4c90fada18","origin":"visual"},{"work_id":"src-5fe467fa61820a5e","frame_id":"FG-bb1991c8d96f6d52","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (1020).jpg","source_page":"https://film-grab.com/2016/01/05/the-big-blue/","scene":"一名短发男子赤裸上身，面部布满汗珠，仰头凝视上方。背景为青蓝色墙壁，两侧可见壁灯，画面呈现极端的仰视视角。","analysis":"采用极端的仰视构图，镜头从下向上拍摄，人物头部位于画面中心，颈部线条清晰可见。人物面部及额头有明显的高光反射，显示出汗水或油脂的质感。背景墙面占据大部分空间，呈现出冷调的青蓝色，左右两侧的壁灯作为环境元素平衡了画面，光线柔和且带有明显的冷色滤镜感。","prompt":"一张电影质感的仰视视角画面，主体为一名短发男子的头部和颈部，他赤裸着肩膀，面部皮肤上覆盖着明显的汗珠，在光线下闪烁。男子双眼向上凝视，神情专注。背景是大面积的冷调青蓝色墙壁，墙面带有简约的线条装饰。画面左侧边缘可见一盏带有白色灯罩的壁灯，右下角也有模糊的灯具轮廓。整体光线偏冷，营造出一种紧张或压抑的氛围，人物轮廓在蓝色背景的衬托下显得立体而清晰。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:47:25-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (1020).jpg","observed_dimensions":[1024,435],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.504,"observed_resolution":"normal","observation_limits":[],"id":"VP-7290161c0bb8c6e6","origin":"visual"},{"work_id":"src-5fe467fa61820a5e","frame_id":"FG-8e5c87d28379636a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (1000).jpg","source_page":"https://film-grab.com/2016/01/05/the-big-blue/","scene":"一名长发人物侧身坐于室内，低头注视前方，背景是漆黑的夜色与模糊的城市灯光，人物占据画面左侧，右侧为大面积暗部。","analysis":"人物位于画面左侧三分之一处，呈现侧脸及上半身，长发披散，身着深色衣物，颈部可见浅色饰物。背景极度虚化，散布着绿色与白色的圆形光斑，暗示窗外的城市夜景。光线从左侧微弱地照亮人物面部和头发，形成柔和的轮廓，整体色调偏冷暗，明暗对比强烈，营造出静谧、孤独的氛围。","prompt":"画面左侧坐着一名长发人物，侧脸朝向右下方，神情专注或沉思。人物身穿深色外套，颈部佩戴浅色珠串或饰物，双手置于身前。背景是深邃的黑色，点缀着失焦的圆形光斑，呈现出夜晚城市灯光的虚化效果，光斑颜色以冷绿和白色为主。光线昏暗，主要光源似乎来自左侧，勾勒出人物的面部轮廓和发丝细节，整体画面色调阴郁、静谧，具有强烈的电影质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:47:32-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (1000).jpg","observed_dimensions":[1024,435],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.521,"observed_resolution":"normal","observation_limits":[],"id":"VP-785f449c23709381","origin":"visual"},{"work_id":"src-5fe467fa61820a5e","frame_id":"FG-33598db7e9c4953c","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (911).jpg","source_page":"https://film-grab.com/2016/01/05/the-big-blue/","scene":"一名短发男子位于深蓝色水下环境中，身穿深色长袖紧身衣，右手高举握住一根垂直的白色绳索，身体正面朝向镜头，背景为均匀的蓝色水体。","analysis":"画面采用中心构图，人物占据画面中央主要位置，头部至腰部以上清晰可见。视角接近平视，光线从上方透射，在人物面部和肩部形成柔和的高光，其余部分逐渐融入深蓝背景。整体色调为冷蓝色，明暗对比集中在人物轮廓与周围水体的交界处，营造出静谧深邃的视觉氛围。","prompt":"深蓝色水下环境，一名短发男子位于画面中央，身穿深色长袖紧身潜水服，右手高举握住一根垂直的白色绳索，身体正面朝向镜头。背景为均匀的深蓝色水体，光线从上方透射，在人物面部和肩部形成柔和的高光，整体色调冷蓝，氛围静谧深邃，人物上半身清晰可见，周围无其他明显物体。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:47:38-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (911).jpg","observed_dimensions":[1024,435],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.515,"observed_resolution":"normal","observation_limits":[],"id":"VP-5d3bb864f22a2cde","origin":"visual"},{"work_id":"src-5fe467fa61820a5e","frame_id":"FG-5aea2d3f0ad18d2f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (1000).jpg","source_page":"https://film-grab.com/2016/01/05/the-big-blue/","scene":"一名身穿白色衣物的人物在荒凉的山间碎石路面上奔跑，背景是连绵起伏的褐色山峦和蜿蜒的土路，天空呈现灰白色。","analysis":"画面采用广角视野，人物位于画面中下方，全身可见，在广阔的环境中显得渺小。右侧前景是粗糙的岩石峭壁，左侧是干燥的枯草坡地。光线为强烈的自然日光，整体色调偏暖黄与灰褐，天空泛白，呈现出干燥、炎热且空旷的视觉氛围。","prompt":"这是一张写实风格的户外摄影画面。在干旱荒凉的山地环境中，一条灰白色的碎石土路从前景向远处延伸。一名身穿白色无袖上衣和短裤的人物正背对镜头，在路面上奔跑，人物全身可见，身形在画面中较小。画面右侧是巨大的、纹理粗糙的岩石峭壁，占据了显著的前景位置。左侧是覆盖着枯黄杂草的山坡。背景是连绵起伏的褐色山脉，山脊线条清晰，远处还有一条蜿蜒曲折的土路盘旋在山间。天空呈现明亮的灰白色，光线强烈，整体色彩以土黄、灰褐和岩石的灰色为主，营造出一种炎热、干燥且空旷的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T12:44:28+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (1000).jpg","observed_dimensions":[1024,435],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.508,"observed_resolution":"normal","observation_limits":[],"id":"VP-d5ac6ce43b7b3546","origin":"visual"},{"work_id":"src-5fe467fa61820a5e","frame_id":"FG-79c71f281a8fd081","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (1023).jpg","source_page":"https://film-grab.com/2016/01/05/the-big-blue/","scene":"高处俯瞰海湾全景，前景为绿色山坡与岩石，中景是沿海城镇与突出的岩石岬角，远处海面平静，右侧有连绵山脉，天空占据画面上半部。","analysis":"画面采用高角度俯视构图，视野开阔。前景山坡占据下方约三分之一，中景城镇与岬角位于画面中心，远景山脉与海面延伸至地平线。光线均匀柔和，天空呈淡蓝色，海面呈灰蓝色，山坡为暗绿色，整体色调偏冷且带有轻微雾气感，无强烈阴影。","prompt":"高角度俯瞰视角的海岸风景，前景是覆盖着绿色植被和散落岩石的山坡，中景为密集的沿海城镇建筑群，一座突出的岩石岬角伸入平静的灰蓝色海面，远处右侧可见连绵的山脉轮廓，天空占据画面上半部分，呈淡蓝色且带有轻微雾气，整体光线柔和均匀，色调偏冷，呈现出开阔宁静的自然地理景观。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T12:44:35+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (1023).jpg","observed_dimensions":[1024,435],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.506,"observed_resolution":"normal","observation_limits":[],"id":"VP-04011e5014475f44","origin":"visual"},{"work_id":"src-5fe467fa61820a5e","frame_id":"FG-933f1cc15f6f4cc6","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (1020).jpg","source_page":"https://film-grab.com/2016/01/05/the-big-blue/","scene":"一位灰发人物身穿深色衣物，独自坐在石墙前的木椅上。背景是米黄色石砌建筑，右侧有一扇红褐色铁艺大门，前景为灰色水泥矮墙。","analysis":"画面采用平视视角，人物位于画面中下方，全身可见，坐姿端正。人物在画面中占比极小，突显了周围建筑环境的宏大与空旷。光线为柔和的自然散射光，无强烈阴影。色彩以米黄、灰白等中性色为主，右侧红褐色铁门形成视觉焦点。","prompt":"写实风格，平视视角。画面主体为一位灰发人物，身穿深色长袖衣物，独自坐在石墙前的木椅上，全身可见，姿态静止。背景是一栋米黄色石砌建筑，墙面由大块石材堆砌，左上方可见深色窗框。人物右侧是一扇高大的红褐色铁艺大门，带有复杂的卷曲花纹，门框为浅色石材。画面前景是一道横贯底部的灰色水泥矮墙。整体光线柔和均匀，色调偏暖，呈现出一种静谧、孤独的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T12:44:42+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (1020).jpg","observed_dimensions":[1024,435],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.52,"observed_resolution":"normal","observation_limits":[],"id":"VP-eac36867d23ca145","origin":"visual"},{"work_id":"src-5fe467fa61820a5e","frame_id":"FG-40070cc3b667deb3","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (993).jpg","source_page":"https://film-grab.com/2016/01/05/the-big-blue/","scene":"一名赤膊男子站在敞开的窗前，侧身低头，手持电话听筒贴近耳边。窗外是明亮的蓝天与远处的海岸线，室内昏暗，左侧堆放着衣物杂物。","analysis":"构图以窗户为框架，将人物置于明亮的室外背景前，形成强烈的逆光剪影效果。人物上半身及大腿部分可见，身体轮廓清晰，头部低垂。室内处于阴影中，仅能辨识左侧家具与杂物的轮廓，右侧窗框边缘可见。光线从窗外射入，色彩对比强烈，室外为冷色调的蓝白，室内为暖色调的暗红与深褐。","prompt":"画面呈现一个昏暗的室内空间，中央是一扇敞开的白色木框窗户，强烈的自然光从窗外射入。一名赤膊男子站在窗前，身体侧向左侧，头部低垂，右手持黑色电话听筒贴近耳边，左手自然下垂，下身穿着深色短裤。窗外是明亮的蓝天和远处的海岸线，视野开阔。室内左侧阴影中堆放着杂乱的衣物和家具，右侧窗框边缘可见，整体色调对比强烈，人物在逆光下呈现半剪影状态，轮廓清晰。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T12:44:50+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (993).jpg","observed_dimensions":[1024,435],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.497,"observed_resolution":"normal","observation_limits":[],"id":"VP-d45598d3e22dfade","origin":"visual"},{"work_id":"src-5fe467fa61820a5e","frame_id":"FG-04dd0773c6e9ae1d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (900).jpg","source_page":"https://film-grab.com/2016/01/05/the-big-blue/","scene":"画面为极近距离的人脸局部特写，主体为一只睁开的眼睛及周围皮肤，可见浓密的眉毛、睫毛和眼角细节，皮肤表面布满汗珠，背景完全虚化。","analysis":"构图极度紧凑，仅展示人物面部的一小部分，环境占比几乎为零。视角平视，光线从侧上方照射，在眼球表面形成明显的高光反射，皮肤纹理和汗珠在强光下清晰可见，色彩以暖色调的肤色和深色的毛发为主，明暗对比强烈。","prompt":"极近距离的人脸局部特写，画面主体为一只睁开的眼睛，可见浓密的黑色眉毛和长睫毛，眼球呈现灰褐色，瞳孔中有清晰的光源反射。皮肤表面覆盖着细密的汗珠，在强烈的侧光照射下闪烁着湿润的光泽，皮肤纹理、毛孔和细微的皱纹清晰可见。背景完全虚化，无法辨识具体环境，整体色调偏暖，光影对比强烈，展现出极致的细节质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T12:44:57+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (900).jpg","observed_dimensions":[1024,435],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.503,"observed_resolution":"normal","observation_limits":[],"id":"VP-f777d71d81105b0f","origin":"visual"}]};